/**
 * noto-sans-sc-subset.js
 *
 * Embedded Noto Sans SC font subsets plus a pure-Node TrueType layout and
 * rasterisation engine. Consumed by the sibling builders build-figures.js
 * (PNG plates) and build-drawings.js (PDF drawings). Node standard library
 * only; no npm dependencies.
 *
 * ===========================================================================
 * FONT PROVENANCE
 * ===========================================================================
 * Source family : Noto Sans SC                       (source name ID 1)
 * Source file   : NotoSansSC-VF.ttf                  (variable font)
 *                 read from C:/Windows/Fonts/NotoSansSC-VF.ttf on the build
 *                 machine; version string "Version 2.04;241114210130;non-release"
 *                 (source name ID 5); one variation axis `wght` 100..900 with
 *                 default 100; unitsPerEm 1000; 31036 glyphs.
 * Copyright     : (c) 2014-2021 Adobe (http://www.adobe.com/), with Reserved
 *                 Font Name 'Source'.                (source name ID 0)
 * License       : SIL Open Font License, Version 1.1 (source name ID 13)
 * License URL   : http://scripts.sil.org/OFL         (source name ID 14)
 *
 * The two base64 payloads below are static subsets of that variable font,
 * instanced at wght=400 (exported as "regular") and wght=700 ("bold"). Each
 * subset contains only the glyphs reachable from the 1247 code points listed
 * in PROVENANCE.inventory.ranges, which is the union of:
 *   - ASCII U+0020..U+007E;
 *   - every code point >= U+0080 occurring in the submission's proposal.md,
 *     proposal.en.md, report/narrative.md, changelog.md, metrics.json,
 *     sources.json, compliance_matrix.json, standard_matrix.json,
 *     design_depth_matrix.json, assumptions.json, self_check.json, the nine
 *     geometry/*.geojson files, visual/index.html and visual/index.en.html;
 *   - every code point >= U+0080 occurring in the submission's remaining
 *     .md/.json/.geojson/.html/.js/.txt/.csv/.svg/.yml/.yaml files (this file
 *     itself excluded), so that text living outside the list above still
 *     renders;
 *   - a fixed safety set of CJK terms, CJK punctuation, and box-drawing and
 *     arrow symbols used by the figure and drawing builders, together with
 *     every non-ASCII character named in this file's own line-breaking tables.
 * The inventory is therefore a snapshot of the submission's text at build
 * time: characters added to those files afterwards are not in the payloads and
 * will render as .notdef. Rebuild with the recipe below after adding text.
 * Requested but absent from the source font's cmap, therefore not included:
 *   U+2717 ✗
 * Each subset holds 1248 glyphs, counting .notdef.
 *
 * Because updateFontNames was left False, the name table inside each subset
 * still carries the source font's default-instance names (name ID 2
 * "Regular", name ID 6 "NotoSansSC-Thin"). Those strings describe the
 * variable font's default instance, not the instanced weight; the outlines in
 * the "regular" payload are wght=400 and in the "bold" payload wght=700. The
 * copyright (name ID 0), licence notice (name ID 13) and licence URL (name
 * ID 14) records are retained inside both payloads.
 *
 * ===========================================================================
 * REPRODUCING THE PAYLOADS
 * ===========================================================================
 * Built with fontTools 4.63.0 on CPython 3.14.7. For W in (400, 700):
 *
 *   from fontTools.ttLib import TTFont
 *   from fontTools.varLib import instancer
 *   from fontTools import subset
 *
 *   font = TTFont("NotoSansSC-VF.ttf")
 *   inst = instancer.instantiateVariableFont(
 *       font, {"wght": W}, inplace=False, updateFontNames=False)
 *
 *   opts = subset.Options()
 *   opts.layout_features = []
 *   opts.notdef_outline = True
 *   opts.drop_tables += ["BASE", "GDEF", "GPOS", "GSUB", "STAT", "HVAR",
 *                        "gasp", "vhea", "vmtx", "DSIG"]
 *   opts.name_IDs = [0, 1, 2, 3, 4, 5, 6, 13, 14]
 *   opts.name_legacy = False
 *   opts.name_languages = [0x0409]
 *   opts.glyph_names = False
 *   opts.recalc_bounds = True
 *   opts.recalc_timestamp = False
 *   opts.prune_unicode_ranges = True
 *   opts.hinting = False
 *   opts.legacy_kern = False
 *   opts.desubroutinize = False
 *
 *   s = subset.Subsetter(options=opts)
 *   s.populate(unicodes=<code points expanded from PROVENANCE.inventory.ranges>)
 *   s.subset(inst)
 *   inst.save("noto-sans-sc-<regular|bold>.ttf")
 *
 * Resulting tables in both payloads: OS/2 cmap glyf head hhea hmtx loca maxp
 * name post. Both cmaps are format 4 subtables at (platform 0, encoding 3)
 * and (platform 3, encoding 1).
 *
 * ===========================================================================
 * INTEGRITY
 * ===========================================================================
 * regular  301 004 bytes  sha256 8cd3660d105de068ec14b4e8102b7bee6c6cde8a307f4bdc96df6161b5b5bbca
 * bold     300 656 bytes  sha256 36afa3ae05a18cccd5c0d627123e67270ac62304e47721b004c6230809767948
 * verifyPayloads() recomputes both digests from the decoded bytes using
 * node:crypto and throws if either differs.
 *
 * ===========================================================================
 * SCOPE OF THESE STATEMENTS
 * ===========================================================================
 * The statements above describe only what was done to produce this file.
 * "Noto", "Noto Sans SC" and "Source" are used solely as the factual names of
 * the upstream font; no trademark interest, sponsorship, endorsement or
 * affiliation with Google, Adobe or SIL is claimed or implied. No typographic
 * or legal professional has reviewed this file.
 */

